[System.IO.File]::WriteAllBytes($archive, [Convert]::FromBase64String($payload))
if ((Get-FileHash -LiteralPath $archive -Algorithm SHA256).Hash.ToLowerInvariant() -ne 'be282db16394a79c762c7ea709af4905c7ad6d4507b352c57c0720d051447e76') { throw 'Pacote incorreto. Nada foi aplicado.' }
